import os
import sys
import json
from Crypto.Cipher import AES
from Crypto.Util.Padding import pad, unpad
from Crypto.Random import get_random_bytes

def load_cache(cache_file, passphrase):
    try:
        with open(cache_file, 'rb') as f:
            encrypted_data = f.read()
        cipher = AES.new(passphrase.encode(), AES.MODE_EAX)
        decrypted_data = cipher.decrypt(encrypted_data)
        return json.loads(decrypted_data)
    except (IOError, KeyError, json.JSONDecodeError):
        return {}

def save_cache(cache_file, passphrase, data):
    cipher = AES.new(passphrase.encode(), AES.MODE_EAX)
    encrypted_data = cipher.encrypt(json.dumps(data).encode())
    cipher_nonce = cipher.nonce
    with open(cache_file, 'wb') as f:
        f.write(cipher_nonce + encrypted_data)

def evaluate_expression(expr):
    try:
        # Replace division with integer division
        expr = expr.replace('/', '//')
        result = eval(expr, {'__builtins__': None}, {})
        return int(result)
    except:
        return None

def main():
    if 'CACHE_PASS' not in os.environ:
        print("ERROR")
        sys.exit(1)

    passphrase = os.environ['CACHE_PASS']
    cache_file = 'cache.dat'
    key = sys.stdin.readline().strip()

    cache = load_cache(cache_file, passphrase)

    if key in cache:
        print(cache[key])
        sys.exit(0)

    result = evaluate_expression(key)
    if result is None:
        print("ERROR")
        sys.exit(1)

    cache[key] = result
    save_cache(cache_file, passphrase, cache)

    print(result)

if __name__ == "__main__":
    main()

import os
import sys
import json
from cryptography.fernet import Fernet

def load_cache():
    if not os.path.exists('cache.dat'):
        return {}
    try:
        with open('cache.dat', 'rb') as f:
            encrypted_data = f.read()
        fernet = Fernet(os.getenv('CACHE_PASS').encode())
        decrypted_data = fernet.decrypt(encrypted_data)
        return json.loads(decrypted_data.decode())
    except (KeyError, json.JSONDecodeError):
        return {}

def save_cache(cache):
    encrypted_data = Fernet(os.getenv('CACHE_PASS').encode()).encrypt(json.dumps(cache).encode())
    with open('cache.dat', 'wb') as f:
        f.write(encrypted_data)

def main():
    if not os.getenv('CACHE_PASS'):
        print("ERROR")
        sys.exit(1)

    cache = load_cache()
    key = sys.stdin.readline().strip()

    if key in cache:
        print(cache[key])
        sys.exit(0)

    if key.isdigit():
        value = int(key)
        cache[key] = value
        save_cache(cache)
        print(value)
        sys.exit(0)
    else:
        print("ERROR")
        sys.exit(1)

if __name__ == "__main__":
    main()

